"""Responsive staff workspace. No remote fonts or assets required."""
from __future__ import annotations
import html
from datetime import datetime, timezone, timedelta
from urllib.parse import urlencode
import sessions
import upkeep

STYLE='''
:root{--bg:#f5f7fb;--white:#fff;--ink:#1d2940;--muted:#69768c;--line:#e5eaf3;--blue:#5268ed;--soft:#eef1ff;--green:#167d65;--amber:#a66c14;--radius:18px}
*{box-sizing:border-box}body{margin:0;font:15px/1.6 "Segoe UI",Arial,sans-serif;color:var(--ink);background:var(--bg)}a{color:var(--blue);text-decoration:none}button,input,textarea{font:inherit}button,a,input,textarea{outline-offset:4px}button{cursor:pointer}.layout{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:100vh}.side{padding:28px 20px;background:var(--white);border-right:1px solid var(--line);position:sticky;top:0;height:100vh}.brand{display:flex;align-items:center;gap:11px;font-weight:700;letter-spacing:-.3px;font-size:19px}.mark{display:grid;place-items:center;width:36px;height:36px;background:var(--blue);color:white;border-radius:11px}.side small{display:block;color:var(--muted);margin:8px 0 35px 47px}.nav a{display:block;color:var(--muted);padding:12px 14px;border-radius:11px;margin:4px 0}.nav a:first-child{background:var(--soft);color:var(--blue);font-weight:600}.side-note{margin-top:40px;padding:15px;background:var(--bg);border-radius:13px;font-size:12px;color:var(--muted)}.content{min-width:0}.top{padding:17px 36px;border-bottom:1px solid var(--line);background:#ffffffd9;display:flex;justify-content:space-between;align-items:center;gap:14px}.top strong{font-size:14px}.tag{font-size:12px;color:var(--green);background:#eaf7f1;padding:5px 12px;border-radius:99px}.top-actions{display:flex;gap:10px;align-items:center}.btn,button{border:1px solid var(--line);background:white;border-radius:10px;padding:9px 15px;color:var(--ink);font-size:13px}.btn:hover,button:hover{border-color:var(--blue);color:var(--blue)}button.primary{background:var(--blue);border-color:var(--blue);color:white;font-weight:600}button:disabled{cursor:default;opacity:.5}.wrap{max-width:1330px;margin:auto;padding:33px 36px 54px}.heading{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;margin-bottom:24px}h1{font-size:32px;line-height:1.2;letter-spacing:-1px;margin:0 0 9px}p.sub{margin:0;color:var(--muted);font-size:14px}.eyebrow{font-size:11px;letter-spacing:1.2px;color:var(--blue);font-weight:700;text-transform:uppercase;margin-bottom:8px}.filters{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.tab{font-size:12px;border:1px solid var(--line);background:white;color:var(--muted);padding:6px 11px;border-radius:8px}.tab.on{color:var(--blue);background:var(--soft);border-color:#d8dfff}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:25px 0}.stat{background:white;border:1px solid var(--line);border-radius:var(--radius);padding:20px}.stat .label{font-size:12px;color:var(--muted)}.stat b{display:block;font-size:31px;letter-spacing:-1px;margin:7px 0 2px;line-height:1.2}.stat small{color:var(--muted);font-size:11px}.stat.pending b{color:var(--amber)}.stat.auto b{color:var(--green)}.columns{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(260px,1fr);gap:22px}.panel{background:white;border:1px solid var(--line);border-radius:var(--radius);padding:23px;margin-bottom:22px;min-width:0}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}h2{font-size:17px;letter-spacing:-.3px;margin:0;display:flex;align-items:center;gap:9px}.count{font-size:11px;font-weight:500;background:var(--bg);padding:2px 8px;border-radius:20px;color:var(--muted)}.hint{font-size:12px;color:var(--muted);margin:8px 0 0}.search{width:100%;padding:11px 13px;border:1px solid var(--line);border-radius:10px;background:var(--bg);margin-bottom:18px;font-size:13px}.case{border:1px solid var(--line);border-left:3px solid #e4b65e;border-radius:13px;padding:18px;margin-bottom:14px}.case:last-child{margin-bottom:0}.case-head{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-bottom:13px}.contact{font-weight:600;font-size:13px}.show-contact{border:0;padding:0;background:none;font-size:11px;color:var(--muted)}.chip{font-size:10px;padding:3px 8px;border-radius:7px;font-weight:600;background:#fff3dc;color:var(--amber)}.chip.green{color:var(--green);background:#eaf7f1}.chip.blue{color:var(--blue);background:var(--soft)}.chip.red{color:#ac4050;background:#ffedf0}.meta{font-size:11px;color:var(--muted)}.question{font-size:16px;font-weight:600;margin:0 0 10px;line-height:1.5;overflow-wrap:anywhere}.bot-reply{padding:12px 14px;background:var(--bg);border-radius:9px;font-size:13px;color:var(--muted);margin:0 0 13px;overflow-wrap:anywhere}.bot-reply span{display:block;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;margin-bottom:4px}.reply label{display:block;font-size:12px;font-weight:600;margin-bottom:7px}textarea{width:100%;resize:vertical;min-height:87px;padding:12px;border:1px solid var(--line);border-radius:10px;background:white;color:var(--ink);font-size:13px}.actions{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:10px}.actions small{font-size:11px;color:var(--muted)}.quiet{border:0;background:none;padding:8px 0;color:var(--muted);font-size:12px}.empty{padding:24px 15px;border:1px dashed var(--line);border-radius:12px;text-align:center;color:var(--muted);font-size:13px}.empty b{display:block;color:var(--ink);margin-bottom:5px}.hold{border:1px solid #dce2ff;background:#f8f9ff;border-radius:12px;padding:15px;margin-bottom:12px}.hold p{font-size:13px;margin:10px 0}.hold-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.thread{margin:10px 0 14px;font-size:12px;color:var(--muted)}summary{cursor:pointer}.turn{padding:10px 12px;margin-top:8px;border-radius:9px;background:var(--bg);font-size:13px;overflow-wrap:anywhere}.turn span{display:block;font-size:10px;font-weight:700;letter-spacing:.4px;margin-bottom:4px}.turn.staff{border-left:2px solid var(--blue)}.turn.bot{border-left:2px solid var(--green)}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:12px;min-width:430px}th{text-align:left;font-size:10px;font-weight:600;color:var(--muted);padding:10px 7px;border-bottom:1px solid var(--line);text-transform:uppercase;letter-spacing:.4px}td{padding:13px 7px;border-bottom:1px solid var(--line);vertical-align:top;overflow-wrap:anywhere}tr:last-child td{border-bottom:0}.nowrap{white-space:nowrap}.bars{display:flex;align-items:flex-end;height:120px;gap:7px;padding:0 0 23px}.bar{flex:1;display:flex;flex-direction:column;justify-content:flex-end;position:relative;height:100%;min-width:12px}.bar .ok{background:#81b8a7;border-radius:0 0 3px 3px}.bar .esc{background:#e6bd76;border-radius:3px 3px 0 0}.bar span{position:absolute;bottom:-21px;width:100%;text-align:center;font-size:9px;color:var(--muted)}.legend{font-size:11px;color:var(--muted);display:flex;gap:13px;margin-top:7px}.legend i{display:inline-block;width:7px;height:7px;border-radius:2px;background:#81b8a7;margin-right:4px}.legend .amber{background:#e6bd76}.frequent{list-style:none;padding:0;margin:0}.frequent li{display:flex;gap:13px;justify-content:space-between;font-size:13px;padding:11px 0;border-bottom:1px solid var(--line)}.frequent li:last-child{border-bottom:0}.frequent b{font-size:11px;color:var(--muted)}.alert{background:#fff3dc;border:1px solid #f0d9ac;border-radius:12px;padding:15px 18px;font-size:13px;margin-bottom:20px}.alert b{display:block;margin-bottom:4px}.shut{font-size:12px;color:var(--amber);background:#fff8eb;padding:12px;border-radius:9px}.footer{font-size:11px;color:var(--muted);margin-top:15px;max-width:95ch}.test-banner{background:#fff3dc;padding:14px 25px;font-size:13px}.login-body{min-height:100vh;display:grid;place-items:center;padding:28px;background:radial-gradient(ellipse at top left,#e9edff,transparent 60%),var(--bg)}.login{width:100%;max-width:420px;background:white;border:1px solid var(--line);padding:38px;border-radius:24px;box-shadow:0 20px 65px #263b7810}.login .brand{margin-bottom:34px}.login h1{font-size:28px}.login p{color:var(--muted);font-size:13px}.login label{display:block;font-size:12px;font-weight:600;margin:18px 0 7px}.login input{width:100%;padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--bg)}.login button{width:100%;margin-top:23px;padding:12px}.login small{display:block;margin-top:22px;color:var(--muted);font-size:11px}.login-error{padding:11px;background:#fff0f0;border-radius:9px;color:#a93f50!important}.status-note{font-size:11px;color:var(--muted)}[hidden]{display:none!important}
@keyframes enter{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}.panel,.stat{animation:enter .35s ease-out both}button,.btn,.tab{transition:background .15s,border-color .15s,color .15s}@media(prefers-reduced-motion:reduce){.panel,.stat{animation:none}button,.btn,.tab{transition:none}}
@media(max-width:1050px){.layout{grid-template-columns:180px minmax(0,1fr)}.side{padding:24px 14px}.wrap{padding:28px 23px}.top{padding:15px 23px}.columns{grid-template-columns:minmax(0,1fr)}.secondary{display:grid;grid-template-columns:1fr 1fr;gap:18px}.stats{gap:10px}.stat{padding:16px}}
@media(max-width:700px){.layout{display:block}.side{height:auto;position:static;border-right:0;border-bottom:1px solid var(--line);padding:14px 20px}.side small,.side-note,.nav{display:none}.brand{font-size:16px}.top{padding:12px 20px}.wrap{padding:23px 16px}.heading{display:block}h1{font-size:27px}.heading .filters{margin-top:17px}.stats{grid-template-columns:1fr 1fr}.stat b{font-size:27px}.secondary{display:block}.panel{padding:17px}.top .tag{display:none}.case{padding:14px}.actions{align-items:flex-start}.actions small{max-width:120px}.login{padding:28px}}
'''

SCRIPT='''
let leaving=false;
const drafts=()=>Array.from(document.querySelectorAll('textarea')).some(t=>t.value.trim()||t===document.activeElement);
window.addEventListener('beforeunload',e=>{if(!leaving&&drafts()){e.preventDefault();e.returnValue='';}});
document.querySelectorAll('form').forEach(f=>f.addEventListener('submit',e=>{
 if(f.dataset.confirm&&!confirm(f.dataset.confirm)){e.preventDefault();return;}
 if(!f.reportValidity()){e.preventDefault();return;}
 leaving=true;f.querySelectorAll('button[type=submit],button:not([type])').forEach(b=>{b.disabled=true;b.textContent='Please wait…';});
}));
document.querySelectorAll('.show-contact').forEach(b=>b.addEventListener('click',()=>{const el=b.previousElementSibling;const full=el.dataset.full;const masked=el.dataset.masked;const show=el.textContent===masked;el.textContent=show?full:masked;b.textContent=show?'Hide contact':'Show contact';}));
const search=document.getElementById('queue-search');if(search)search.addEventListener('input',()=>{let visible=0;document.querySelectorAll('.case').forEach(c=>{c.hidden=!c.textContent.toLowerCase().includes(search.value.toLowerCase());if(!c.hidden)visible++;});document.getElementById('no-matches').hidden=!!visible;});
setInterval(()=>{if(!drafts()&&!document.querySelector('details[open]')&&!(search&&search.value)){leaving=true;location.reload();}},30000);
window.addEventListener('pageshow',()=>{document.querySelectorAll('button').forEach(b=>{if(b.textContent==='Please wait…'){b.disabled=false;b.textContent=b.closest('form').dataset.button||'Continue';}});});
'''

def ago(iso):
    mins=max(0,int((datetime.now(timezone.utc)-datetime.fromisoformat(iso)).total_seconds()/60))
    return 'just now' if mins<1 else f'{mins}m ago' if mins<60 else f'{mins//60}h ago' if mins<1440 else f'{mins//1440}d ago'

def contact(sender):
    e=html.escape
    masked=('•••• '+sender[-4:]) if sender.isdigit() else 'Test customer'
    full='+'+sender if sender.isdigit() else sender
    return f'<span class="contact" data-full="{e(full)}" data-masked="{e(masked)}">{e(masked)}</span><button type="button" class="show-contact">Show contact</button>'

def thread(turns):
    if not turns:return ''
    body=[]
    for t in turns[-8:]:
        role='customer' if t['role']=='customer' else 'staff' if t['role'] in ('you','staff') else 'bot'
        label={'customer':'Customer','staff':'Staff','bot':'Assistant'}[role]
        body.append(f'<div class="turn {role}"><span>{label}</span>{html.escape(t["text"])}</div>')
    return f'<details class="thread"><summary>Conversation history · {len(turns)} messages</summary>{"".join(body)}</details>'

def login_page(target,csrf,error=''):
    e=html.escape
    warning=f'<p class="login-error" role="alert">{e(error)}</p>' if error else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in · Enquiry desk</title><style>{STYLE}</style></head><body class="login-body"><main class="login"><div class="brand"><span class="mark">F</span>Enquiry desk</div><div class="eyebrow">Staff workspace</div><h1>Welcome back</h1><p>Sign in to review enquiries and follow up with customers.</p>{warning}<form method="post" action="/login" data-button="Sign in"><input type="hidden" name="next" value="{e(target)}"><input type="hidden" name="_csrf" value="{e(csrf)}"><label for="username">Username</label><input id="username" name="username" autocomplete="username" required autofocus><label for="password">Password</label><input id="password" type="password" name="password" autocomplete="current-password" required><button class="primary" type="submit">Sign in</button></form><small>For authorised staff. Your session expires after eight hours or when the service restarts.</small></main></body></html>'''

def render(data,sites,site,days,error=None,csrf_token=''):
    e=html.escape
    title={'sepadental':'SEPA Dental','tiewdental':'Tiew Dental','khengdental':'Kheng Dental'}.get(site,site or 'All businesses')
    total,handled=data['total'],data['handled']
    pct=f'{round(100*handled/total)}%' if total else '—'
    median=f'{data["median_ms"]/1000:.1f}s' if data['median_ms'] is not None else '—'
    waiting,holding,bot=data['waiting'],data['holding'],data['with_bot']
    def hidden(c):
        return f'<input type="hidden" name="site" value="{e(c["site"])}"><input type="hidden" name="sender" value="{e(c["sender"])}"><input type="hidden" name="_csrf" value="{e(csrf_token)}">'
    tabs=''.join(f'<a class="tab{" on" if site==s else ""}" href="?{e(urlencode({"site":s,"days":days}))}">{e(s)}</a>' for s in sites)
    if len(sites)>1:tabs=f'<a class="tab{" on" if not site else ""}" href="?days={days}">All</a>'+tabs
    ranges=''.join(f'<a class="tab{" on" if days==d else ""}" href="?{e(urlencode({**({"site":site} if site else {}),"days":d}))}">{d} days</a>' for d in (7,14,30))
    banner=''
    if error=='length':banner='<div class="alert" role="alert"><b>The reply is too long.</b>Shorten it to 2,000 characters and try again. No message was sent.</div>'
    if error=='send':banner='<div class="alert" role="alert"><b>The reply could not be sent.</b>The customer has not been answered. The enquiry is still waiting. Check the connection or recipient settings and try again.</div>'
    if error=='window':banner='<div class="alert" role="alert"><b>The WhatsApp reply window has closed.</b>A normal message cannot be sent from here. Wait for a new customer message, or use an approved contact method.</div>'
    holds=[]
    for c in holding:
        until=(datetime.fromisoformat(c['until']).astimezone(timezone(timedelta(hours=8))).strftime('%I:%M %p')+' MYT') if c['until'] else 'you give it back'
        holds.append(f'<div class="hold"><div class="hold-head"><div>{contact(c["sender"])}</div><span class="chip blue">Staff handling</span></div><p>{e(c["question"] or "Customer conversation")}</p><div class="actions"><span class="meta">Assistant paused until {e(until)}</span><form method="post" action="/dashboard/resume" data-button="Give back to assistant">{hidden(c)}<button type="submit">Give back to assistant</button></form></div>{thread(data["threads"].get((c["site"],c["sender"]),[]))}</div>')
    holding_html=f'<section class="panel" id="handling"><div class="panel-head"><h2>Staff handling <span class="count">{len(holding)}</span></h2></div>{"".join(holds)}</section>' if holds else ''
    cases=[]
    for c in waiting:
        mins=c['window']
        window='' if mins is None else '<span class="chip red">Reply window closed</span>' if mins<=0 else f'<span class="chip">{mins//60}h {mins%60}m to reply</span>'
        form=(f'<form class="reply" method="post" action="/dashboard/reply" data-button="Send on WhatsApp">{hidden(c)}<label for="reply-{c["id"]}">Your reply</label><textarea id="reply-{c["id"]}" name="text" maxlength="2000" required placeholder="Write a helpful reply. Confirm only what you know."></textarea><div class="actions"><small>Sends a real message to this customer.</small><button type="submit" class="primary">Send on WhatsApp</button></div></form>' if mins is None or mins>0 else '<p class="shut">More than 24 hours have passed since the last customer message. Normal replies are unavailable until they message again.</p>')
        cases.append(f'<article class="case"><div class="case-head">{contact(c["sender"])}<span class="chip">Needs follow-up</span>{window}<span class="meta">{ago(c["at"])}</span></div><p class="question">{e(c["question"] or "No question recorded")}</p><div class="bot-reply"><span>Assistant replied</span>{e(c["reply"] or "No reply recorded")}</div>{thread(data["threads"].get((c["site"],c["sender"]),[]))}{form}<form method="post" action="/dashboard/close" data-confirm="Close this enquiry without sending a reply?" data-button="Close without replying">{hidden(c)}<button type="submit" class="quiet">Close without replying</button></form></article>')
    queue=''.join(cases) if cases else '<div class="empty"><b>No enquiries waiting</b>New requests needing staff will appear here.</div>'
    bot_rows=''.join(f'<tr><td class="nowrap">{ago(c["at"])}</td><td class="nowrap">{e(c["sender"][-4:])}</td><td>{e(c["question"] or "—")}</td><td><form method="post" action="/dashboard/close" data-button="End chat" data-confirm="End this conversation?">{hidden(c)}<button class="quiet" type="submit">End chat</button></form></td></tr>' for c in bot)
    active=f'<section class="panel"><div class="panel-head"><h2>Assistant handling <span class="count">{len(bot)}</span></h2></div><div class="scroll"><table><thead><tr><th>Last activity</th><th>Contact ends</th><th>Latest question</th><th></th></tr></thead><tbody>{bot_rows}</tbody></table></div><p class="hint">Conversations become fresh sessions after {sessions.SESSION_HOURS} hours of inactivity.</p></section>' if bot else ''
    recent_rows=[]
    for r in data['recent']:
        outcome='<span class="chip green">Assistant replied</span>' if r['answerable'] else '<span class="chip">Needs staff</span>'
        recent_rows.append(f'<tr><td class="nowrap">{ago(r["at"])}</td><td class="nowrap">•••• {e(r["sender"][-4:])}</td><td>{e(r["question"])}</td><td>{outcome}</td><td class="nowrap">{f'{r["latency_ms"]/1000:.1f}s' if r["latency_ms"] is not None else '—'}</td></tr>')
    recent=f'<div class="scroll"><table><thead><tr><th>When</th><th>Customer</th><th>Question</th><th>Routing</th><th>Answer time</th></tr></thead><tbody>{"".join(recent_rows)}</tbody></table></div>' if recent_rows else '<div class="empty">No answered questions in this period.</div>'
    bars=[]
    peak=max([d['total'] for d in data['daily']],default=1) or 1
    for d in data['daily']:
        bars.append(f'<div class="bar" title="{e(d["day"])}: {d["total"]} questions"><div class="esc" style="height:{round(100*(d["total"]-d["handled"])/peak,1)}%"></div><div class="ok" style="height:{round(100*d["handled"]/peak,1)}%"></div><span>{e(d["day"][-2:])}</span></div>')
    chart=f'<div class="bars">{"".join(bars)}</div><div class="legend"><span><i></i>Assistant replied</span><span><i class="amber"></i>Needs staff</span></div>' if bars else '<div class="empty">Activity appears as questions arrive.</div>'
    top=''.join(f'<li><span>{e(t["question"])}</span><b>{t["n"]}</b></li>' for t in data['top']) or '<li>No repeated questions yet.</li>'
    logout=f'<form method="post" action="/logout" data-button="Sign out"><input type="hidden" name="_csrf" value="{e(csrf_token)}"><button type="submit">Sign out</button></form>' if csrf_token else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · Enquiry desk</title><style>{STYLE}</style></head><body><div class="layout"><aside class="side"><div class="brand"><span class="mark">F</span>Enquiry desk</div><small>Customer conversations</small><nav class="nav"><a href="#overview">Overview</a><a href="#waiting">Needs follow-up</a><a href="#handling">Staff handling</a><a href="#activity">Recent activity</a></nav><div class="side-note">Answer what is supported.<br>Confirm what is uncertain.<br>Keep the customer informed.</div></aside><div class="content"><header class="top"><strong>{e(title)}</strong><div class="top-actions"><span class="tag">Staff workspace</span><a class="btn" href="?{e(urlencode({**({"site":site} if site else {}),"days":days}))}">Refresh</a>{logout}</div></header><main class="wrap" id="overview"><div class="heading"><div><div class="eyebrow">WhatsApp enquiries</div><h1>Customer enquiries</h1><p class="sub">Review requests, reply with confidence and keep follow-up moving.</p></div><div class="filters">{ranges}</div></div><div class="filters">{tabs}</div>{banner}<div class="stats"><div class="stat"><span class="label">Questions received</span><b>{total}</b><small>In the last {days} days</small></div><div class="stat auto"><span class="label">Assistant reply rate</span><b>{pct}</b><small>Routing measure, not accuracy</small></div><div class="stat pending"><span class="label">Waiting for staff</span><b>{len(waiting)}</b><small>Current open queue</small></div><div class="stat"><span class="label">Median answer time</span><b>{median}</b><small>Excludes message delivery</small></div></div><div class="columns"><div>{holding_html}<section class="panel" id="waiting"><div class="panel-head"><h2>Needs follow-up <span class="count">{len(waiting)}</span></h2><span class="status-note">Refreshes every 30s</span></div><input class="search" type="search" id="queue-search" aria-label="Search waiting enquiries" placeholder="Search waiting enquiries…">{queue}<div id="no-matches" class="empty" hidden>No matching enquiries.</div></section>{active}</div><div class="secondary"><section class="panel"><div class="panel-head"><h2>Question activity</h2></div>{chart}</section><section class="panel"><div class="panel-head"><h2>Common questions</h2></div><ol class="frequent">{top}</ol></section></div></div><section class="panel" id="activity"><div class="panel-head"><h2>Recent questions</h2><span class="status-note">Last {days} days</span></div>{recent}</section><footer class="footer">AI replies can contain mistakes. Review important facts and leave bookings or policy decisions for authorised confirmation. A staff queue entry is not a completed resolution. Normal WhatsApp replies are available within 24 hours of the customer's last message. Times shown in MYT. {e(upkeep.policy())}</footer></main></div></div><script>{SCRIPT}</script></body></html>'''
